dotProduct :: Vec 1024 FixedP -> Vec 1024 FixedP -> FixedP
dotProduct a b = sum (zipWith (*) a b)
rankerCore :: Signal System (Vec 1024 FixedP) -> Signal System FixedP
rankerCore input = dotProduct <$> input <*> pure (repeat 1)
EOF
