cat << 'EOF' > "${SRC_DIR}/hw/rtl/MemoryArbiter.hs"
module MemoryArbiter where
import Clash.Prelude
type DataW = 128
data ArbitrationState = Idle | GrantA | GrantB deriving (Show, Eq, Enum, Bounded)
memArbiter :: Signal System (BitVector DataW) -> Signal System (BitVector DataW) -> Signal System (BitVector DataW)
memArbiter a b = mealy step Idle (bundle (a,b))
  where
    step st (x,y) = let out = case st of { Idle -> 0; GrantA -> x; GrantB -> y }
                        st' = case st of { Idle -> GrantA; GrantA -> GrantB; GrantB -> GrantA }
                    in (st', out)
EOF
