cat << 'EOF' > "${SRC_DIR}/zk/inference_trace.circom"
pragma circom 2.0.0;
template InferenceTrace(n) {
    signal input input[n];
    signal input weights[n][n];
    signal input bias[n];
    signal output out[n];
    signal intermediate[n];
    for (var i = 0; i < n; i++) {
        intermediate[i] <== 0;
        for (var j = 0; j < n; j++) {
            intermediate[i] <== intermediate[i] + input[j] * weights[j][i];
        }
        intermediate[i] <== intermediate[i] + bias[i];
        out[i] <== intermediate[i];
    }
}
component main = InferenceTrace(16);
