----------------------------- MODULE IPC_Liveness -----------------------------
EXTENDS TLC, Integers, Sequences
VARIABLES queue, producer, consumer
TypeOK == /\ queue \in Seq(Nat) /\ producer \in Nat /\ consumer \in Nat
Init == /\ queue = << >> /\ producer = 0 /\ consumer = 0
Produce == /\ Len(queue) < 10 /\ queue' = Append(queue, producer) /\ producer' = producer + 1 /\ UNCHANGED consumer
Consume == /\ Len(queue) > 0 /\ consumer' = Head(queue) /\ queue' = Tail(queue) /\ UNCHANGED producer
Next == Produce \/ Consume
Spec == Init /\ [][Next]_<<queue,producer,consumer>>
THEOREM TypeOK => []TypeOK
=============================================================================
EOF
cat << 'EOF' > "${SRC_DIR}/verification/spin/ipc.pml"
#define CAPACITY 4096
chan channel = [CAPACITY] of { byte };
int head = 0;
int tail = 0;
proctype Producer() {
  do
  :: (tail < CAPACITY) -> channel!1; tail = (tail + 1) % CAPACITY
  od
}
proctype Consumer() {
  byte data;
  do
  :: (head != tail) -> channel?data; head = (head + 1) % CAPACITY
  od
}
init { run Producer(); run Consumer(); }
EOF
cat << 'EOF' > "${SRC_DIR}/main.zig"
const std = @import("std");
const types = @import("core/types.zig");
const tensor_mod = @import("core/tensor.zig");
const memory = @import("core/memory.zig");
pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    defer _ = gpa.deinit();
    const test_mem_size: usize = 128;
    var guard = try memory.MemoryGuard.init(test_mem_size);
    defer guard.deinit();
    if (!memory.checkCanary(guard.ptr, test_mem_size)) @panic("canary");
    const fp_a = types.FixedPoint32.fromFloat(10.0);
    const fp_b = types.FixedPoint32.fromFloat(2.5);
    const fp_c = types.FixedPoint32.mul(fp_a, fp_b);
    if (@abs(fp_c.toFloat() - 25.0) > 0.1) @panic("fixedpoint");
    var shape = [_]usize{ 2, 2 };
    var t = try tensor_mod.Tensor.init(allocator, &shape);
    defer t.deinit();
    t.set(&.{0, 0}, 1.0);
    std.debug.print("ok\n", .{});
}
EOF
